use vstd::prelude::*;

verus! {

    /// Copy all elements of `a` into a new Vec and return it.
    /// Ensures the result has the same length and contents as `a`.
    fn copy<T: Copy>(a: &Vec<T>) -> (result: Vec<T>)
        ensures
            result.len() == a.len(),
            forall |j: nat| j < a.len() ==> result.index(j) == a.index(j),
    {
        let mut result: Vec<T> = Vec::new();
        let mut idx: usize = 0;
        // Loop over all indices 0 .. a.len(), pushing a[idx] onto result.
        while idx < a.len()
            invariant
                // idx never exceeds the length of a
                idx <= a.len(),
                // result has length equal to the number of elements we've copied so far
                result.len() == idx,
                // for each copied position j < idx, result[j] == a[j]
                forall |j: nat| j < idx ==> result.index(j) == a.index(j),
            decreases
                a.len() - idx,
        {
            // Safe to index because idx < a.len()
            let x: T = a.index(idx);
            result.push(x);
            idx = idx + 1;
        }
        result
    }

}

